Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Segmentos RFQ · barra = % do volume 12M, traço = % dos clientes"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "format(datum[''Clientes''], '',.0f'') + '' clientes · R$ '' + format(datum[''Fat''] / 1000000, '',.1f'') + '' mi''",
      "as": "txt"
    }
  ],
  "encoding": {
    "y": {
      "field": "Segmento",
      "type": "nominal",
      "sort": [
        "Campeões",
        "Leais",
        "Ocasionais",
        "Em risco",
        "Sem compra 12M"
      ],
      "axis": {
        "title": null,
        "labelColor": "#F2F4F5",
        "labelFontSize": 13,
        "labelPadding": 12
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#252E36",
        "height": {
          "band": 0.56
        }
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "x2": {
          "datum": 1
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "height": {
          "band": 0.56
        },
        "cornerRadiusEnd": 3
      },
      "encoding": {
        "x": {
          "field": "PctQtd",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ]
          },
          "axis": {
            "format": ".0%",
            "title": null,
            "grid": true,
            "gridDash": [
              2,
              3
            ],
            "values": [
              0,
              0.25,
              0.5,
              0.75,
              1
            ]
          }
        },
        "color": {
          "field": "Segmento",
          "type": "nominal",
          "scale": {
            "domain": [
              "Campeões",
              "Leais",
              "Ocasionais",
              "Em risco",
              "Sem compra 12M"
            ],
            "range": [
              "#FF8C00",
              "#FFB45C",
              "#8A98A4",
              "#E5484D",
              "#4A5862"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Segmento"
          },
          {
            "field": "Regra",
            "title": "Regra"
          },
          {
            "field": "Clientes",
            "format": ",.0f"
          },
          {
            "field": "PctCli",
            "format": ".1%",
            "title": "% dos clientes"
          },
          {
            "field": "Qtd",
            "format": ",.0f",
            "title": "Baterias 12M"
          },
          {
            "field": "PctQtd",
            "format": ".1%",
            "title": "% do volume 12M"
          },
          {
            "field": "Fat",
            "format": ",.0f",
            "title": "Faturamento 12M (R$)"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#F2F4F5",
        "thickness": 2.5,
        "bandSize": 30
      },
      "encoding": {
        "x": {
          "field": "PctCli",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 8,
        "fontSize": 13,
        "fontWeight": 600,
        "color": "#F2F4F5"
      },
      "encoding": {
        "x": {
          "field": "PctQtd",
          "type": "quantitative"
        },
        "text": {
          "field": "PctQtd",
          "format": ".0%"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "bottom",
        "dy": -16,
        "fontSize": 10,
        "color": "#9AA6B0"
      },
      "encoding": {
        "x": {
          "datum": 1
        },
        "text": {
          "field": "txt"
        }
      }
    }
  ]
}'
